// Original indexmap2.14 range, truncate, Drain and hash-index mutation observer.
#![feature(panic_can_unwind,panic_internals)]
use indexmap::{IndexMap,map::Drain}; use serde_json::{json,Value};
use std::{cell::{Cell,RefCell},rc::Rc,hash::{Hash,Hasher,BuildHasher},io::{self,BufRead},panic::{self,AssertUnwindSafe},ops::{Bound,RangeBounds},mem::ManuallyDrop};
thread_local!{static TRACE:Cell<bool>=const{Cell::new(false)};}
struct Log{trace:bool,events:Vec<String>,fail:String,failed:bool}type L=Rc<RefCell<Log>>;
fn step(l:&L,s:String){let event=format!("{s}:{}",std::thread::panicking());let fail={let mut log=l.borrow_mut();log.events.push(event.clone());let yes=!log.failed&&log.fail==event;if yes{log.failed=true};yes};if l.borrow().trace{println!("E:{}",json!(event))}if fail{panic!("fail")}}
struct K{id:u64,log:L}impl Hash for K{fn hash<H:Hasher>(&self,h:&mut H){step(&self.log,format!("hash:{}",self.id));h.write_u64(self.id)}}impl PartialEq for K{fn eq(&self,r:&Self)->bool{step(&self.log,format!("eq:{}:{}",self.id,r.id));self.id==r.id}}impl Eq for K{}impl Drop for K{fn drop(&mut self){step(&self.log,format!("kdrop:{}",self.id))}}
struct V{id:u64,log:L}impl Drop for V{fn drop(&mut self){step(&self.log,format!("vdrop:{}",self.id))}}
struct B{log:L,mask:u64}struct H{log:L,mask:u64,state:u64}impl Hasher for H{fn write(&mut self,_:&[u8]){panic!("unexpected write")}fn write_u64(&mut self,n:u64){step(&self.log,format!("u64:{n}"));self.state=n}fn finish(&self)->u64{step(&self.log,"finish".into());self.state&self.mask}}impl Drop for H{fn drop(&mut self){step(&self.log,"hdrop".into())}}impl BuildHasher for B{type Hasher=H;fn build_hasher(&self)->H{step(&self.log,"build".into());H{log:self.log.clone(),mask:self.mask,state:0}}}impl Drop for B{fn drop(&mut self){step(&self.log,"bdrop".into())}}
struct BoundVal{kind:u64,value:usize}impl BoundVal{fn borrow(&self)->Bound<&usize>{match self.kind{0=>Bound::Unbounded,1=>Bound::Included(&self.value),2=>Bound::Excluded(&self.value),_=>panic!("bad bound")}}}
struct R{log:L,start:[BoundVal;2],end:[BoundVal;2],starts:Cell<usize>,ends:Cell<usize>}impl RangeBounds<usize>for R{fn start_bound(&self)->Bound<&usize>{let n=self.starts.get();self.starts.set(n+1);step(&self.log,format!("start:{n}"));self.start[n.min(1)].borrow()}fn end_bound(&self)->Bound<&usize>{let n=self.ends.get();self.ends.set(n+1);step(&self.log,format!("end:{n}"));self.end[n.min(1)].borrow()}}impl Drop for R{fn drop(&mut self){step(&self.log,"rdrop".into())}}
fn n(q:&Value,k:&str)->usize{q[k].as_u64().unwrap_or(0)as usize}fn b(q:&Value,k:&str)->BoundVal{BoundVal{kind:q[k][0].as_u64().unwrap_or(0),value:q[k][1].as_u64().unwrap_or(0)as usize}}
fn pairs<'a>(it:impl Iterator<Item=(&'a K,&'a V)>)->Value{json!(it.map(|(k,v)|(k.id,v.id)).collect::<Vec<_>>())}
fn take(value:Option<(K,V)>)->Value{match value{Some(pair)=>{let result=json!([pair.0.id,pair.1.id]);drop(pair);result},None=>Value::Null}}
fn error(p:Box<dyn std::any::Any+Send>)->Value{if let Some(s)=p.downcast_ref::<String>(){json!(s)}else if let Some(s)=p.downcast_ref::<&str>(){json!(s)}else{json!("opaque")}}
fn action(q:&Value)->Value{
 let l=Rc::new(RefCell::new(Log{trace:false,events:Vec::new(),fail:String::new(),failed:false}));let mut m=IndexMap::with_capacity_and_hasher(n(q,"capacity"),B{log:l.clone(),mask:q["mask"].as_u64().unwrap()});for i in 0..n(q,"n"){m.insert(K{id:i as u64,log:l.clone()},V{id:10+i as u64,log:l.clone()});}
 {let mut log=l.borrow_mut();log.events.clear();log.trace=q["trace"].as_bool().unwrap_or(false);TRACE.with(|t|t.set(log.trace));log.fail=q["fail"].as_str().unwrap_or("").into();}
 let mut holder:Option<Drain<'_,K,V>>=None;let mut forgotten=false;
 let log_ref=&l;let map_ref=Some(&mut m);let holder_ref=&mut holder;let forgotten_ref=&mut forgotten;
 let result=panic::catch_unwind(AssertUnwindSafe(move ||{
  let l=log_ref;let m=map_ref.unwrap();let holder=holder_ref;
  if q["op"]=="truncate"{m.truncate(n(q,"nth"));return Value::Null}
  let r=R{log:l.clone(),start:[b(q,"start"),b(q,"again_start")],end:[b(q,"end"),b(q,"again_end")],starts:Cell::new(0),ends:Cell::new(0)};
  if q["op"]=="get"{return m.get_range(r).map(|s|pairs(s.iter())).unwrap_or(Value::Null)}
  if q["op"]=="get_mut"{return m.get_range_mut(r).map(|s|{for(_,v)in s.iter_mut(){v.id+=1000}pairs(s.iter())}).unwrap_or(Value::Null)}
  *holder=Some(m.drain(r));let it=holder.as_mut().unwrap();for _ in 0..n(q,"front"){drop(it.next())}for _ in 0..n(q,"back"){drop(it.next_back())}
  match q["op"].as_str().unwrap(){"next"=>take(it.next()),"back"=>take(it.next_back()),"nth"=>take(it.nth(n(q,"nth"))),"nth_back"=>take(it.nth_back(n(q,"nth"))),"count"=>json!(holder.take().unwrap().count()),"last"=>take(holder.take().unwrap().last()),"close"=>{drop(holder.take());Value::Null},"forget"=>{std::mem::forget(holder.take().unwrap());*forgotten_ref=true;Value::Null},"inspect"=>pairs(it.as_slice().iter()),_=>panic!("bad op")}
 }));let(value,panic)=match result{Ok(v)=>(v,Value::Null),Err(p)=>(Value::Null,error(p))};let remaining=holder.as_ref().map(|d|pairs(d.as_slice().iter()));let len=holder.as_ref().map(|d|d.len());let hint=holder.as_ref().map(|d|d.size_hint());let events=l.borrow().events.clone();{let mut log=l.borrow_mut();log.fail.clear();log.events.clear();}drop(holder);let close_events=l.borrow().events.clone();l.borrow_mut().events.clear();let map_after=pairs(m.as_slice().iter());let capacity=m.capacity();let mut queries=Vec::new();for i in 0..n(q,"n")+2{let key=ManuallyDrop::new(K{id:i as u64,log:l.clone()});if forgotten{queries.push(match panic::catch_unwind(AssertUnwindSafe(||m.get(&*key).map(|v|v.id))){Ok(v)=>json!({"value":v,"panic":Value::Null}),Err(p)=>json!({"value":Value::Null,"panic":error(p)})})}else{queries.push(json!(m.get(&*key).map(|v|v.id)))}}let query_events=l.borrow().events.clone();l.borrow_mut().events.clear();drop(m);let drop_events=l.borrow().events.clone();json!({"value":value,"panic":panic,"remaining":remaining,"len":len,"hint":hint,"events":events,"close_events":close_events,"map":map_after,"capacity":capacity,"queries":queries,"query_events":query_events,"drop_events":drop_events})
}
struct OnDrop<F:FnOnce()>(Option<F>);impl<F:FnOnce()>Drop for OnDrop<F>{fn drop(&mut self){self.0.take().unwrap()()}}
fn run(q:&Value)->Value{if q["inherited"].as_bool().unwrap_or(false){let mut result=None;let _=panic::catch_unwind(AssertUnwindSafe(||{let _g=OnDrop(Some(||result=Some(action(q))));panic!("outer")}));result.unwrap()}else{action(q)}}
fn hook(info:&panic::PanicHookInfo<'_>){if !TRACE.with(Cell::get){return}let(payload,kind)=if let Some(v)=info.payload().downcast_ref::<&str>(){((*v).to_owned(),"static_str")}else if let Some(v)=info.payload().downcast_ref::<String>(){(v.clone(),"owned_string")}else{("opaque".into(),"opaque")};println!("H:{}",json!({"Payload":payload,"Kind":kind,"Location":info.location().map(|l|json!({"File":l.file(),"Line":l.line(),"Column":l.column()})),"CanUnwind":info.can_unwind(),"ForceNoBacktrace":info.force_no_backtrace()}))}
fn main(){panic::set_hook(Box::new(hook));for line in io::stdin().lock().lines(){let q:Value=serde_json::from_str(&line.unwrap()).unwrap();let result=if q["processing"].as_bool().unwrap_or(false){let request=q.clone();let output=std::sync::Arc::new(std::sync::Mutex::new(None));let result=output.clone();panic::set_hook(Box::new(move|info|{hook(info);let value=action(&request);*result.lock().unwrap()=Some(value)}));let _=panic::catch_unwind(||panic!("outer"));panic::set_hook(Box::new(hook));output.lock().unwrap().take().unwrap()}else{run(&q)};println!("{}",json!({"request":q,"result":result}))}}
